import React, { useState } from "react";

export default function MobileNavigationMegaMenuComponent() {
  const [menuOpen, setMenuOpen] = useState(false);
  const [openSubmenu, setOpenSubmenu] = useState(null);

  // Toggle hamburger menu
  const toggleMenu = () => {
    setMenuOpen(!menuOpen);
  };

  // Toggle accordion submenus
  const toggleSubmenu = (index) => {
    setOpenSubmenu(openSubmenu === index ? null : index);
  };

  return (
    <div className="mobile-navigations-bar header">
      <nav className="mobile-navbar">
        <div className="mobile-logo">
          <a href="https://www.accorian.com/" target="_blank" rel="noreferrer">
            <img
              src="https://www.accorian.com/wp-content/uploads/2024/10/Accorian-Logo.svg"
              alt="Accorian Logo"
            />
          </a>
        </div>
        <div className="mobile-hamburger" onClick={toggleMenu}>
          <i
            className={`bi ${menuOpen ? "bi-x" : "bi-list"}`}
            id="mobile-hamburger-icon"
          ></i>
        </div>
      </nav>

      <ul
        className="mobile-menu"
        style={{ display: menuOpen ? "flex" : "none" }}
      >
        <li>
          <a href="https://www.accorian.com/" target="_blank" rel="noreferrer">
            Home
          </a>
        </li>

        {/* Example Submenu (Services) */}
        <li
          className={`mobile-has-submenu ${
            openSubmenu === 0 ? "mobile-open" : ""
          }`}
        >
          <a
            href="#"
            onClick={(e) => {
              e.preventDefault();
              toggleSubmenu(0);
            }}
          >
            Services
          </a>
          <ul
            className="mobile-submenu"
            style={{ display: openSubmenu === 0 ? "block" : "none" }}
          >
            <li>
              <a
                href="https://www.accorian.com/hitrust/"
                target="_blank"
                rel="noreferrer"
              >
                HITRUST®
              </a>
            </li>
            {/* 👉 You can continue converting all other nested <li> same way */}
          </ul>
        </li>

        {/* Other links (shortened for example) */}
        <li>
          <a href="https://www.accorian.com/securing-ai/">Securing AI</a>
        </li>
        <li>
          <a href="https://www.accorian.com/contact-us/" target="_blank" rel="noreferrer">
            Contact Us
          </a>
        </li>
      </ul>
    </div>
  );
}
